-- Hardening (2026-07-15): add server-side file type/size limits to the
-- medical-certs upload bucket used by hr-staff.html.
--
-- IMPORTANT:
-- - Run this against the HR Supabase project only:
--   ybyseaenceyswjnwdmdf
-- - Do not run this against the booking project:
--   xfhpwxjywqgqefbncumm
-- - This file intentionally does not change bucket public/private access.
--   It only enforces upload type/size and scopes anon inserts to the object
--   key format generated by hr-staff.html.

-- hr-staff.html accepts JPG, PNG, and PDF medical certificates, max 5MB.
update storage.buckets
set allowed_mime_types = array['image/jpeg','image/png','application/pdf'],
    file_size_limit = 5242880
where id = 'medical-certs';

-- hr-staff.html writes objects as:
--   <employeeId>/<timestamp>.<jpg|jpeg|png|pdf>
drop policy if exists "anon can upload medical certs" on storage.objects;
create policy "anon can upload medical certs"
on storage.objects for insert to anon
with check (
  bucket_id = 'medical-certs'
  and name ~* '^[^/]+/[0-9]+\.(jpg|jpeg|png|pdf)$'
);
